from pathlib import Path

# Extract key text from pptx and docx for grounding the revision matrix.
assets = {
    'pptx': Path('assets/ppt_pack/76bb19d2_开题报告-颜雍颀-V3.pptx'),
    'docx': Path('assets/uploads/fde1237c_开题报告-颜雍颀(1).docx')
}

results = []

# PPTX extraction
try:
    from pptx import Presentation
    prs = Presentation(str(assets['pptx']))
    results.append('=== PPTX ===')
    for i, slide in enumerate(prs.slides, 1):
        texts = []
        for shape in slide.shapes:
            if hasattr(shape, 'text'):
                t = shape.text.strip()
                if t:
                    texts.append(t.replace('\r', ' ').replace('\n', ' | '))
        if texts:
            joined = ' || '.join(texts[:8])
            results.append(f'Slide {i}: {joined[:1200]}')
except Exception as e:
    results.append(f'PPTX extraction failed: {e}')

# DOCX extraction
try:
    from docx import Document
    doc = Document(str(assets['docx']))
    results.append('=== DOCX ===')
    paras = []
    for p in doc.paragraphs:
        t = p.text.strip()
        if t:
            paras.append(t)
    for idx, t in enumerate(paras[:120], 1):
        results.append(f'P{idx}: {t}')
except Exception as e:
    results.append(f'DOCX extraction failed: {e}')

print('\n'.join(results))

from zipfile import ZipFile
from pathlib import Path
import xml.etree.ElementTree as ET


def extract_pptx_text(path):
    ns = {
        'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
        'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'
    }
    out = []
    with ZipFile(path) as z:
        slide_files = sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')])
        for sf in slide_files:
            root = ET.fromstring(z.read(sf))
            texts = []
            for t in root.findall('.//a:t', ns):
                if t.text and t.text.strip():
                    texts.append(t.text.strip())
            if texts:
                num = sf.split('slide')[-1].split('.xml')[0]
                out.append(f'--- Slide {num} ---')
                out.append(' | '.join(texts[:120]))
    return '\n'.join(out)


def extract_docx_text(path):
    ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    with ZipFile(path) as z:
        root = ET.fromstring(z.read('word/document.xml'))
    paras = []
    for p in root.findall('.//w:p', ns):
        texts = []
        for t in p.findall('.//w:t', ns):
            if t.text:
                texts.append(t.text)
        text = ''.join(texts).strip()
        if text:
            paras.append(text)
    return '\n'.join(f'{i+1}. {p}' for i, p in enumerate(paras[:220]))

pptx_path = Path('assets/ppt_pack/76bb19d2_开题报告-颜雍颀-V3.pptx')
docx_path = Path('assets/uploads/fde1237c_开题报告-颜雍颀(1).docx')

print('=== PPTX ===')
print(extract_pptx_text(pptx_path)[:25000])
print('\n=== DOCX ===')
print(extract_docx_text(docx_path)[:25000])
